<div class="card form"><h1>🚀 Create Account</h1><form id="register"><label>Full name</label><input name="full_name" required><label>Email</label><input type="email" name="email" required><label>Password (8+ characters)</label><input type="password" name="password" minlength="8" required><label>Account type</label><select name="role"><option value="student">Student</option><option value="parent">Parent</option></select><label>Language</label><select name="language"><option value="en">English</option><option value="ar">العربية</option></select><input type="hidden" name="csrf" value="<?=h(csrfToken())?>"><button class="btn">Create account</button></form><div id="msg"></div></div><script>document.getElementById('register').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);f.append('action','register');try{let r=await post('backend/api/auth.php',f);location.href='index.php?page='+(r.role==='parent'?'parent':'dashboard')}catch(x){document.getElementById('msg').innerHTML='<div class="notice error">'+escapeHTML(x.message)+'</div>'}}</script>
